import{_ as t,o as d,c as a,a2 as o}from"./chunks/framework.D7WGirly.js";const l=JSON.parse('{"title":"Key tokens","description":"The key names a Tuimark keymap accepts in keys=\\"…\\".","frontmatter":{"title":"Key tokens","description":"The key names a Tuimark keymap accepts in keys=\\"…\\".","editLink":false,"head":[["link",{"rel":"canonical","href":"https://tuimark.vercel.app/reference/keys"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Tuimark"}],["meta",{"property":"og:title","content":"Key tokens | Tuimark"}],["meta",{"property":"og:description","content":"The key names a Tuimark keymap accepts in keys=\\"…\\"."}],["meta",{"property":"og:url","content":"https://tuimark.vercel.app/reference/keys"}],["meta",{"name":"twitter:title","content":"Key tokens | Tuimark"}],["meta",{"name":"twitter:description","content":"The key names a Tuimark keymap accepts in keys=\\"…\\"."}]]},"headers":[],"relativePath":"reference/keys.md","filePath":"reference/keys.md","lastUpdated":1790532435000}'),r={name:"reference/keys.md"};function c(n,e,s,i,p,k){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="key-tokens" tabindex="-1">Key tokens <a class="header-anchor" href="#key-tokens" aria-label="Permalink to &quot;Key tokens&quot;">​</a></h1><p>A <code>&lt;bind keys=&quot;…&quot;&gt;</code> row takes one or more of these tokens, separated by commas: <code>keys=&quot;q,ctrl+c&quot;</code>. The same names are the steps of <code>tuimark play --input</code>. See <a href="/guide/interaction">Keymap, actions and focus</a>.</p><h2 id="named-keys" tabindex="-1">Named keys <a class="header-anchor" href="#named-keys" aria-label="Permalink to &quot;Named keys&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Token</th><th>Key</th></tr></thead><tbody><tr><td><code>enter</code></td><td>Enter / Return</td></tr><tr><td><code>esc</code></td><td>Escape</td></tr><tr><td><code>tab</code></td><td>Tab</td></tr><tr><td><code>backspace</code></td><td>Backspace</td></tr><tr><td><code>space</code></td><td>Space bar</td></tr><tr><td><code>up</code></td><td>Arrow up</td></tr><tr><td><code>down</code></td><td>Arrow down</td></tr><tr><td><code>left</code></td><td>Arrow left</td></tr><tr><td><code>right</code></td><td>Arrow right</td></tr><tr><td><code>home</code></td><td>Home</td></tr><tr><td><code>end</code></td><td>End</td></tr><tr><td><code>pgup</code></td><td>Page up</td></tr><tr><td><code>pgdn</code></td><td>Page down</td></tr><tr><td><code>shift+tab</code></td><td>Shift + Tab</td></tr></tbody></table><h2 id="other-tokens" tabindex="-1">Other tokens <a class="header-anchor" href="#other-tokens" aria-label="Permalink to &quot;Other tokens&quot;">​</a></h2><p>Also valid: <code>ctrl+&lt;a-z&gt;</code> (<code>ctrl+i</code>, <code>ctrl+j</code>, and <code>ctrl+m</code> arrive as <code>tab</code>/<code>enter</code> and never match), and any single printable ASCII character except space (write <code>space</code>) and <code>,</code> (the <code>keys=</code> list separator; a token of <code>,</code> binds nothing).</p>',6)])])}const h=t(r,[["render",c]]);export{l as __pageData,h as default};
